mapper.insert:
INSERT INTO housedeals (apt_seq, apt_dong, floor, deal_year, deal_month, deal_day, exclu_use_ar, deal_amount) SELECT v.apt_seq, v.apt_dong, v.floor, v.deal_year, v.deal_month, v.deal_day, v.exclu_use_ar, v.deal_amount FROM (
SELECT CONCAT('BT', #{item.lawdCd}, '-', SUBSTRING(MD5(CONCAT_WS('|', #{item.lawdCd}, #{item.dong}, #{item.jibun}, #{item.aptName})), 1, 10)) AS apt_seq, '' AS apt_dong, CAST(#{item.floor} AS CHAR) AS floor, CAST(SUBSTRING(#{item.dealDate}, 1, 4) AS UNSIGNED) AS deal_year, CAST(SUBSTRING(#{item.dealDate}, 6, 2) AS UNSIGNED) AS deal_month, CAST(SUBSTRING(#{item.dealDate}, 9, 2) AS UNSIGNED) AS deal_day, #{item.area} AS exclu_use_ar, CAST(#{item.dealAmount} AS CHAR) AS deal_amount
) v WHERE v.deal_year IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM housedeals hd WHERE hd.apt_seq = v.apt_seq AND hd.deal_year = v.deal_year AND hd.deal_month = v.deal_month AND hd.deal_day = v.deal_day AND CAST(REPLACE(COALESCE(hd.deal_amount, '0'), ',', '') AS UNSIGNED) = CAST(v.deal_amount AS UNSIGNED) AND COALESCE(hd.exclu_use_ar, 0) = COALESCE(v.exclu_use_ar, 0) AND COALESCE(hd.floor, '') = COALESCE(v.floor, '') )

mapper.update:
UPDATE houseinfos
SET latitude = #{latitude},
    longitude = #{longitude}
WHERE apt_seq = #{aptSeq}

mapper.select:
SELECT 'LOCAL_DB' AS source_type, COALESCE(hi.sgg_cd, #{lawdCd}) AS lawd_cd, CASE WHEN hd.deal_year > 0 AND hd.deal_month > 0 THEN CONCAT(hd.deal_year, LPAD(hd.deal_month, 2, '0')) ELSE #{dealYmd} END AS deal_ymd, COALESCE(hi.apt_nm, '') AS apt_name, COALESCE(hi.umd_nm, '') AS dong, COALESCE(hi.jibun, '') AS jibun, CAST(REPLACE(COALESCE(hd.deal_amount, '0'), ',', '') AS UNSIGNED) AS deal_amount, COALESCE(hd.exclu_use_ar, 0) AS area, CAST(REPLACE(COALESCE(hd.floor, '0'), ',', '') AS SIGNED) AS floor, COALESCE(hi.build_year, 0) AS build_year, CASE WHEN hd.deal_year > 0 AND hd.deal_month > 0 AND hd.deal_day > 0 THEN DATE_FORMAT(STR_TO_DATE(CONCAT(hd.deal_year, LPAD(hd.deal_month, 2, '0'), LPAD(hd.deal_day, 2, '0')), '%Y%m%d'), '%Y-%m-%d') ELSE '' END AS deal_date, TRIM(REGEXP_REPLACE(CONCAT(COALESCE(dc.sido_name, ''), ' ', COALESCE(dc.gugun_name, ''), ' ', COALESCE(hi.umd_nm, ''), ' ', COALESCE(hi.jibun, '')), '[[:space:]]+', ' ')) AS raw_address FROM housedeals hd JOIN houseinfos hi ON hd.apt_seq = hi.apt_seq LEFT JOIN dongcodes dc ON dc.dong_code = CONCAT(hi.sgg_cd, hi.umd_cd)
AND hi.sgg_cd = #{lawdCd}
AND hd.deal_year = CAST(SUBSTRING(#{dealYmd}, 1, 4) AS UNSIGNED) AND hd.deal_month = CAST(SUBSTRING(#{dealYmd}, 5, 2) AS UNSIGNED)
ORDER BY hd.deal_year DESC, hd.deal_month DESC, hd.deal_day DESC, hd.no DESC LIMIT #{limit}
